// Check (iv): snarkjs 0.7.5 `groth16.verify` on proofs generated by the Rust crate.
// Input: out/rust-proofs.json (written by `cargo test` in crates/lowki-groth16, or by the
// wasm test via `make verify-wasm`). Also re-derives the Solidity calldata from each Rust
// proof with Kohaku's own encoding (toWithdrawProof / encodeRagequitPayload) and compares.
//
// Run: npx tsx verify-rust-proofs.ts [path/to/rust-proofs.json]
import { readFileSync } from "node:fs";
import * as snarkjs from "snarkjs";
import { decodeFunctionData } from "viem";
import { KOHAKU, kohakuEncoding } from "./kohaku.ts";

const ARTIFACTS =
  process.env.LOWKI_PP_ARTIFACTS ?? "/Users/betterclever/projects/ethglobal/vendor/npm/circuits/package/artifacts";
const file = process.argv[2] ?? new URL("./out/rust-proofs.json", import.meta.url).pathname;
const proofs = JSON.parse(readFileSync(file, "utf8")) as any[];
const vkeys: Record<string, any> = {
  commitment: JSON.parse(readFileSync(`${ARTIFACTS}/commitment.vkey`, "utf8")),
  withdraw: JSON.parse(readFileSync(`${ARTIFACTS}/withdraw.vkey`, "utf8")),
};
const { toWithdrawProof, encodeRagequitPayload } = await kohakuEncoding();
const { poolAbi } = await import(`${KOHAKU}/packages/privacy-pools/src/data/abis/pool.abi.ts`);
const dec = (x: bigint) => x.toString(10);
const solidityOf = (circuit: string, proof: any, publicSignals: string[]) => {
  let s: any;
  if (circuit === "withdraw") s = toWithdrawProof({ proof, publicSignals } as any);
  else s = (decodeFunctionData({ abi: poolAbi, data: encodeRagequitPayload({ proof, publicSignals } as any) }).args as any)[0];
  return JSON.stringify({ pA: s.pA.map(dec), pB: s.pB.map((r: bigint[]) => r.map(dec)), pC: s.pC.map(dec), pubSignals: s.pubSignals.map(dec) });
};

let failed = 0;
for (const p of proofs) {
  const ok = await snarkjs.groth16.verify(vkeys[p.circuit], p.publicSignals, p.proof);
  // negative control: snarkjs must reject a tampered public signal
  const bad = [...p.publicSignals];
  bad[0] = (BigInt(bad[0]) + 1n).toString();
  const rejects = !(await snarkjs.groth16.verify(vkeys[p.circuit], bad, p.proof));
  const solOk = solidityOf(p.circuit, p.proof, p.publicSignals) === JSON.stringify(p.solidity);
  const pass = ok && rejects && solOk;
  if (!pass) failed++;
  console.log(
    `${pass ? "PASS" : "FAIL"} ${p.name}: snarkjs.verify=${ok} tampered-rejected=${rejects} kohaku-solidity-match=${solOk}`,
  );
}
console.log(`${proofs.length - failed}/${proofs.length} Rust proofs accepted by snarkjs 0.7.5 (${file})`);
await (globalThis as any).curve_bn128?.terminate?.();
process.exit(failed === 0 && proofs.length > 0 ? 0 : 1);
